#include "../k4_k5/TestCounter.h"
#include "eda-virtual-board/State13.h"
#include "eda-virtual-board/Phase2Faults.h"
#include "eda-virtual-board/VirtualInstruments.h"
#include "eda-virtual-board/BlindProjection.h"
#include "eda-platform/Platform.h"
#include <iostream>
#include <fstream>
namespace vb=eda::virtual_board;using eda::Json;namespace fs=std::filesystem;
size_t checks=0;void Check(bool yes,const std::string& s){++checks;if(!yes)throw std::runtime_error(s);}
Json Read(const fs::path& path){std::ifstream input(path);if(!input)throw std::runtime_error("E_FIXTURE_READ");return Json::parse(input);}
Json Rule(std::string id,std::string type,std::string target,std::string kind,std::string hook,Json effect=Json::object()){effect["type"]=type;return {{"id",id},{"enabled",true},{"visibility","student_visible"},{"target",{{"id",target},{"kind",kind}}},{"hook",hook},{"effect",effect},{"trigger",{{"kind","permanent"},{"start_tick","0"}}}};}
int main(int argc,char** argv){if(argc!=3)return 2;fs::path root=eda::platform::PathFromUtf8(argv[1]),out=eda::platform::PathFromUtf8(argv[2]);fs::create_directories(out);Json report;try{
    for(unsigned a=0;a<32;++a){Check(vb::CombineState13(a,a)==a,"table idempotence");Check(vb::CombineState13(2,a)==a && vb::CombineState13(a,2)==a,"FLT identity at product code 2");for(unsigned b=0;b<32;++b)Check(vb::CombineState13(a,b)==vb::CombineState13(b,a),"1024 table symmetry");}
    Check(vb::CombineState13(13,23)==23 && vb::CombineState13(15,21)==21,"Ideal dominates Strong without fresh CON");Check(vb::CombineState13(21,23)==54,"opposite Ideal is explicit table contention");Check(vb::CombineState13(29,23)==61,"Power dominates Ideal with CON");Check(vb::CombineState13(5,15)==15,"Strong ignores opposite weak pull");Check(vb::CombineState13(13,15)==46,"opposite Strong retains flag plus internal undecided base");
    auto ideal=vb::ExplainState13({{"a",13},{"b",15},{"c",23}});Check(ideal.at("state_code")==23 && ideal.at("sticky_conflict")==true && !ideal.at("contention").get<bool>(),"historical weak-source conflict is separate from Ideal-dominated final byte");Check(!vb::ResolveState13({{"reserved",8}}).supported && !vb::ResolveState13({{"PUD-not-in-product",28}}).supported,"reserved input strengths and uncontracted PUD are rejected");
    {auto frozen=Read(root/"registry/logic/state13.v1.json");for(int a=0;a<32;++a)for(int b=0;b<32;++b)Check(frozen.at("table")[a][b]==vb::State13Table()[a*32+b],"frozen 1024 cell artifact matches compiled table");}
    auto explained=vb::ExplainState13({{"z",15},{"a",13}});Check(explained.at("drivers")[0]["driver_id"]=="a" && explained.at("fold_steps").size()==2 && explained.at("conflict_sources").size()==1 && explained.at("contention"),"sorted explanatory chain matches physical contention");Check(vb::GetHighMask13({{"a",7},{"b",13},{"c",2}})==1 && vb::GetDrivenMask13({{"a",7},{"b",13},{"c",2}})==3,"separate driven/high masks");
    auto c=m0test::Contract(root);auto descriptor=c.board->Descriptor();descriptor["electrical"]["resolver_version"]=vb::State13Version;descriptor["electrical"]["state_encoding"]=vb::State13Version;descriptor["version"]="2.0.0";c.board=std::make_shared<const vb::BoardTopology>(descriptor,c.electrical);c.phase2=true;c.fault_profile=vb::Phase1Faults::EmptyProfile(*c.board);
    auto bridge=Rule("bridge-private","bridge","pad.10","node","topology.transform",{{"other_node","pad.11"}});c.fault_profile["faults"]={bridge};vb::VirtualSession s(c,m0test::Factory());auto initial=s.Submit({{"op","get"}});Check(!initial.at("board").at("nodes").at("pad.10").at("contention").get<bool>(),"same-level bridge is not an error flag");auto frame=m0test::Start(s);Check(frame.at("board").at("nodes").at("pad.10").at("contention"),"bridge unifies opposite DUT drivers before resolve");
    auto before=frame.at("input_writes");s.Submit({{"op","probe.attach"},{"probe_id","left"},{"target","wire.led0.a"}});auto probe=s.Submit({{"op","probe.read"},{"probe_id","left"}});Check(probe.at("instrument_reply").at("read_only") && probe.at("input_writes")==before,"probe never imports or drives DUT");
    auto stopped=s.Submit(m0test::Cmd("stop","stop"));auto records=s.Submit({{"op","journal"}}).at("records");for(int repeat=0;repeat<3;++repeat){auto replay=vb::VirtualSession::ReplayCommitted(c,m0test::Factory(),records);Check(replay.at("circuit_digest")==stopped.at("digests").at("circuit") && replay.at("control_digest")==stopped.at("digests").at("control"),"extended topology three from-zero replays match");}
    auto clean=c;clean.fault_profile=vb::Phase1Faults::EmptyProfile(*c.board);clean.fault_profile["faults"]={Rule("missing-pull","pull_removal","pad.3:board-pullup-p3","driver","driver.transform")};vb::VirtualSession pulled(clean,m0test::Factory());auto guard=pulled.Submit({{"op","get"}});Check(guard.at("reason")=="UnknownInput" && guard.at("input_writes")=="0","pull removal makes actual un-driven input FLT before import");pulled.Submit(m0test::Set("key_p3",13,"press"));Check(pulled.Submit(m0test::Cmd("step","recover")).at("reason")=="StepComplete","remaining contact source repairs removed pull");
    auto mapping=Rule("map","mapping_overlay","effective","pad_map","mapping.overlay",{{"bindings",Json::array({{{"port_ref","led_n[0]"},{"pad",11}},{{"port_ref","led_n[1]"},{"pad",10}}})}});clean.fault_profile["faults"]={mapping};vb::VirtualSession mapped(clean,m0test::Factory());auto mf=m0test::Start(mapped);Check(mf.at("board").at("leds").at("led1").at("lit") && !mf.at("board").at("leds").at("led0").at("lit").get<bool>(),"mapping overlay redirects actual source without editing CST");Check(mf.at("pad_map").at("original")!=mf.at("pad_map").at("effective"),"original and effective PadMap retained independently");
    auto student=vb::StudentProjection(mf,"opaque-public-token-01234567890123456789");Check(student.dump().find("\"faults\"")==std::string::npos && student.dump().find("\"p1\"")==std::string::npos && student.dump().find("\"pad_map\"")==std::string::npos && !vb::StudentCommandAllowed("profile.load") && !vb::StudentCommandAllowed("fault.revoke") && !vb::StudentCommandAllowed("replay.file"),"C++ runner projection and allowlist exclude private checkpoints, effective mappings and mutation capabilities");
    report={{"status","passed"},{"checks",checks},{"explanation",explained}};
}catch(const std::exception& e){report={{"status","failed"},{"checks",checks},{"error",e.what()}};std::cerr<<e.what()<<std::endl;}std::ofstream(out/"native.json")<<report.dump(2);std::cout<<report.dump()<<std::endl;return report.at("status")=="passed"?0:1;}
